55	test('có index, đủ thuộc tính, không uv', () => { /* index != null; position, normal, color, aRole; uv undefined */ });
56	test('đèn pha ở nửa đầu xe (+X), đèn hậu ở nửa đuôi', () => { /* mọi đỉnh Role.Head có x > 0, Role.Tail có x < 0; mỗi loại có cả hai */ });
57	test('siêu xe và xe tay ga có đỉnh Paint; xe tay ga có Accent và Helmet; buýt không có Paint', () => {});
58	test('hình học gộp ≤ maxVerts, aPart đúng 3 giá trị 0,1,2', () => { /* vhBuildFleetGeometry().getAttribute('position').count <= CONFIG.vehicles.maxVerts */ });
59	test('mặt hướng ra ngoài: pháp tuyến mỗi tam giác của thân loft không chỉ vào tâm khối', () => { /* với car: ≥ 95 % tam giác có dot(normal, tâmTamGiác − tâmBBox) > 0 */ });
