1	import * as THREE from 'three';
2	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
3	import { CONFIG, type BoatTypeId } from '../../config';
4	
5	/* =====================================================================
6	   HÌNH HỌC TÀU — 5 kiểu (spec §6): A du thuyền hai thân, B tàu gỗ kiểu cũ, C du thuyền 3 tầng, D tàu cá / hàng, E tàu buồm cao.
7	   Dựng theo mét ở chiều dài danh nghĩa rồi chuẩn hóa: dài 1 theo Z (mũi về +Z), đáy ngay dưới mặt nước y = 0.
8	   Fleet scale đều theo len ⇒ mọi tỉ lệ cao/rộng giữ theo kiểu.
9	   Mỗi đỉnh: color (màu ban ngày), uv (biển tên → ô atlas 0, phần khác → ô trắng), aGlow (loại đèn đêm, xem Glow).
10	   ===================================================================== */
11	export enum Glow { None = 0, Window = 1, Led = 2, NavRed = 3, NavGreen = 4, Plate = 5, Lantern = 6, Stripe = 7 }   // Stripe: sọc thân, không phát sáng, đổi màu theo biến thể
12	export const BOAT_TYPES: BoatTypeId[] = ['A', 'B', 'C', 'D', 'E'];
13	export const ATLAS_ROWS = CONFIG.boats.names.length + 1;   // atlas biển tên: mỗi tên một hàng + hàng cuối trắng
14	const WHITE_V = 1 - 0.5 / ATLAS_ROWS;                      // v giữa hàng trắng
15	
16	const C = CONFIG.boats.palette;   // màu ban ngày (config.ts)
17	const LANTERN = C.lanterns;
18	
19	/* Một bộ phận: bỏ index, gán màu, glow, uv (ô trắng trừ biển tên) */
20	function part(g: THREE.BufferGeometry, color: number, glow: Glow): THREE.BufferGeometry {
21	  const p = g.index ? g.toNonIndexed() : g; p.clearGroups();
22	  const n = p.getAttribute('position').count, col = new THREE.Color(color), c = new Float32Array(n * 3), gl = new Float32Array(n);
23	  for (let i = 0; i < n; i++) { c[i * 3] = col.r; c[i * 3 + 1] = col.g; c[i * 3 + 2] = col.b; gl[i] = glow; }
24	  p.setAttribute('color', new THREE.BufferAttribute(c, 3)); p.setAttribute('aGlow', new THREE.BufferAttribute(gl, 1));
25	  if (glow !== Glow.Plate) { const uv = new Float32Array(n * 2); for (let i = 0; i < n; i++) { uv[i * 2] = 0.5; uv[i * 2 + 1] = WHITE_V; } p.setAttribute('uv', new THREE.BufferAttribute(uv, 2)); }
26	  return p;
27	}
28	
29	/* Người dựng một kiểu tàu: tích các bộ phận rồi gộp + chuẩn hóa */
30	class Kit {
31	  parts: THREE.BufferGeometry[] = [];
32	  add(g: THREE.BufferGeometry, color: number, glow = Glow.None) { this.parts.push(part(g, color, glow)); }
33	  box(sx: number, sy: number, sz: number, x: number, y: number, z: number, color: number, glow = Glow.None, rx = 0) {
34	    const g = new THREE.BoxGeometry(sx, sy, sz); if (rx) g.rotateX(rx); this.add(g.translate(x, y, z), color, glow);
35	  }
36	  /* Khối lăng trụ đứng từ mặt bằng (x, z), từ y0 lên y1 — thân tàu, cabin mũi tròn */
37	  prism(pts: [number, number][], y0: number, y1: number, color: number, glow = Glow.None) {
38	    const s = new THREE.Shape(pts.map(([x, z]) => new THREE.Vector2(x, -z)));
39	    const g = new THREE.ExtrudeGeometry(s, { depth: y1 - y0, bevelEnabled: false, curveSegments: 4 }).rotateX(-Math.PI / 2).translate(0, y0, 0);
40	    this.add(g, color, glow);
41	  }
42	  /* Mặt bằng thân: đuôi vuông ở z0, thon dần về mũi nhọn ở z1 (bow = phần dài vuốt) */
43	  hullPlan(hw: number, z0: number, z1: number, bow: number): [number, number][] {
44	    const zb = z1 - bow;
45	    return [[-hw, z0], [hw, z0], [hw, zb], [hw * 0.75, zb + bow * 0.5], [hw * 0.3, z1 - bow * 0.12], [0, z1], [-hw * 0.3, z1 - bow * 0.12], [-hw * 0.75, zb + bow * 0.5], [-hw, zb]];
46	  }
47	  /* Cabin mũi bo: chữ nhật, mặt trước tròn */
48	  cabinPlan(hw: number, z0: number, z1: number, round: number): [number, number][] {
49	    const pts: [number, number][] = [[-hw, z0], [hw, z0]];
50	    for (let i = 0; i <= 6; i++) { const a = (i / 6) * Math.PI / 2; pts.push([hw * Math.cos(a), z1 - round + round * Math.sin(a)]); }
51	    for (let i = 5; i >= 0; i--) { const a = (i / 6) * Math.PI / 2; pts.push([-hw * Math.cos(a), z1 - round + round * Math.sin(a)]); }
