163	const cache = new Map<BoatTypeId, THREE.BufferGeometry>();
164	export function btBuildTypeGeometry(type: BoatTypeId): THREE.BufferGeometry {
165	  if (!cache.has(type)) { const k = new Kit(); BUILDERS[type](k); cache.set(type, k.build()); }
