170	export function btBuildFleetGeometry(types: BoatTypeId[]): THREE.BufferGeometry {
171	  const parts = types.map((t) => {
172	    const g = btBuildTypeGeometry(t).clone(), n = g.getAttribute('position').count;
173	    g.setAttribute('aPart', new THREE.BufferAttribute(new Float32Array(n).fill(BOAT_TYPES.indexOf(t)), 1));
174	    return g;
175	  });
176	  const g = mergeGeometries(parts, false)!;
177	  g.computeBoundingSphere();
178	  return g;
179	}
