97	  g.add(box(M.tail, 0.06, 0.07, 1.5, -2.26, 0.72));                                    // dải đèn hậu
98	  g.add(box(M.dark, 0.12, 0.2, 1.5, -2.22, 0.45));                                     // khuếch tán sau
99	  g.add(box(M.dark, 0.3, 0.05, 1.7, 2.12, 0.16));                                      // cánh gió trước
100	  g.add(box(M.dark, 0.34, 0.04, 1.7, -2.05, 0.98)); for (const z of [0.7, -0.7]) g.add(box(M.dark, 0.1, 0.12, 0.05, -2.0, 0.92, z));   // cánh gió sau
