128	/* ---------- xe buýt nhỏ vàng, dải xanh trắng (không dùng logo thật) ---------- */
129	function busSideTex(flip) {
130	  const W = 1024, H = 384, c = document.createElement('canvas'); c.width = W; c.height = H; const x = c.getContext('2d');
131	  x.fillStyle = '#f2c11c'; x.fillRect(0, 0, W, H);
132	  const band = (col, a, b) => { x.fillStyle = col; x.beginPath(); x.moveTo(W, H * (0.80 + b)); x.lineTo(W, H * (0.62 - a)); x.lineTo(W * 0.4, H * (0.54 - a)); x.lineTo(0, H * (0.16 - a)); x.lineTo(0, H * (0.40 + b)); x.lineTo(W * 0.4, H * (0.68 + b)); x.closePath(); x.fill(); };
133	  band('#ffffff', 0.05, 0.05); band('#2f9be0', 0, 0);
134	  x.fillStyle = '#0e1318'; x.fillRect(W * 0.1, H * 0.06, W * 0.9, H * 0.46);
135	  x.fillStyle = '#3d5567'; for (let i = 0; i < 4; i++) x.fillRect(W * (0.115 + i * 0.222), H * 0.09, W * 0.205, H * 0.4);
136	  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 8;
137	  if (flip) { t.wrapS = THREE.RepeatWrapping; t.repeat.x = -1; t.offset.x = 1; }
138	  return t;
139	}
